CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE,pass VARCHAR(255),name VARCHAR(100),role ENUM('admin','user') DEFAULT 'user',bio VARCHAR(300) NOT NULL DEFAULT '',avatar VARCHAR(100) NULL,lang VARCHAR(8) NOT NULL DEFAULT '') DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS settings(k VARCHAR(40) PRIMARY KEY,v TEXT) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS rooms(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(16) UNIQUE,name VARCHAR(100),description TEXT NULL,chat_enabled TINYINT DEFAULT 0,guest_enabled TINYINT DEFAULT 0,rec_enabled TINYINT DEFAULT 1) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS room_members(room_id INT,user_id INT,is_manager TINYINT DEFAULT 0,can_mic TINYINT DEFAULT 0,can_cam TINYINT DEFAULT 0,can_screen TINYINT DEFAULT 0,can_board TINYINT DEFAULT 0,PRIMARY KEY(room_id,user_id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS participants(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT,user_id INT NULL,name VARCHAR(100),is_guest TINYINT DEFAULT 0,can_mic TINYINT DEFAULT 0,can_cam TINYINT DEFAULT 0,can_screen TINYINT DEFAULT 0,can_board TINYINT DEFAULT 0,mic_on TINYINT DEFAULT 0,cam_on TINYINT DEFAULT 0,screen_on TINYINT DEFAULT 0,joined_at DATETIME,last_seen DATETIME,left_at DATETIME NULL,KEY(room_id,left_at)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS signals(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT,from_pid INT,to_pid INT,type VARCHAR(10),data MEDIUMTEXT,created DATETIME DEFAULT CURRENT_TIMESTAMP,KEY(room_id,id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS chat(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT,name VARCHAR(100),text VARCHAR(600),owner VARCHAR(20) DEFAULT '',deleted_at DATETIME NULL,created DATETIME DEFAULT CURRENT_TIMESTAMP,KEY(room_id,id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS recordings(id INT AUTO_INCREMENT PRIMARY KEY,room_id INT,file VARCHAR(100),size BIGINT UNSIGNED NOT NULL DEFAULT 0,created DATETIME DEFAULT CURRENT_TIMESTAMP) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS auth_tokens(id INT AUTO_INCREMENT PRIMARY KEY,selector VARCHAR(24) UNIQUE,hash CHAR(64),user_id INT,expires DATETIME,KEY(user_id)) DEFAULT CHARSET=utf8mb4;
